"""Weekly timesheet rows, one line of text per worker."""

from typing import List
from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from collections import Counter

def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")

def _line(name: str, count: int, minutes: int) -> str:
    hours = f"{minutes / 60:.1f}"
    return f"{name}: {count} shifts, {hours} hours"

# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    _check(shifts)
    count = Counter(shift.worker for shift in shifts)
    mins = worker_minutes(shifts)
    rank = lambda name: (-mins[name], name)
    return [_line(name, count[name], mins[name])
            for name in sorted(count, key=rank)]
